namespace Erlang.Differential;

public static class NumericBoundaryCaseSources
{
    public const string AbsBitBoundaries = "-module(oracle_numeric_abs_bit_boundaries).\n-export([run/0]).\nrun() ->\n    P=f(1), N=f(16#8000000000000001), 0=bits(abs(f(16#8000000000000000))), 1=bits(abs(P)), 1=bits(abs(N)), 16#7fefffffffffffff=bits(abs(f(16#ffefffffffffffff))),\n    done.\nf(Bits) -> <<V:64/float>> = <<Bits:64>>, V.\nbits(V) -> <<B:64>> = <<V:64/float>>, B.\n";
    public const string FloatPreservesBits = "-module(oracle_numeric_float_preserves_bits).\n-export([run/0]).\nrun() ->\n    lists:foreach(fun(B)->B=bits(float(f(B))) end,[0,16#8000000000000000,1,16#8000000000000001,16#7fefffffffffffff,16#ffefffffffffffff]),\n    done.\nf(Bits) -> <<V:64/float>> = <<Bits:64>>, V.\nbits(V) -> <<B:64>> = <<V:64/float>>, B.\n";
    public const string FloatNearestEven = "-module(oracle_numeric_float_nearest_even).\n-export([run/0]).\nrun() ->\n    A=1 bsl 53, A=float_to_integer(float(A+1)), B=A+4, B=float_to_integer(float(A+3)), C= -A, C=float_to_integer(float(-A-1)), D= -A-4, D=float_to_integer(float(-A-3)), E=1 bsl 100, E=float_to_integer(float(E+(1 bsl 46))), F=E+(1 bsl 48), F=float_to_integer(float(E+3*(1 bsl 46))),\n    done.\nfloat_to_integer(F) -> trunc(F).\n";
    public const string FloatOverflowThreshold = "-module(oracle_numeric_float_overflow_threshold).\n-export([run/0]).\nrun() ->\n    Max=(1 bsl 1024)-(1 bsl 971), Half=1 bsl 970, 16#7fefffffffffffff=bits(float(Max)), 16#7fefffffffffffff=bits(float(Max+Half-1)), 16#ffefffffffffffff=bits(float(-Max-Half+1)), bad(Max+Half), bad(-Max-Half), bad(1 bsl 1024), bad(-(1 bsl 1024)),\n    done.\nf(Bits) -> <<V:64/float>> = <<Bits:64>>, V.\nbits(V) -> <<B:64>> = <<V:64/float>>, B.\nbad(X) -> try float(X) of _ -> error(expected_badarg) catch error:badarg -> ok end.\n";
    public const string RoundHalfNeighbours = "-module(oracle_numeric_round_half_neighbours).\n-export([run/0]).\nrun() ->\n    [0,1,1,0,-1,-1]=[round(f(B))||B<-[16#3fdfffffffffffff,16#3fe0000000000000,16#3fe0000000000001,16#bfdfffffffffffff,16#bfe0000000000000,16#bfe0000000000001]], [4503599627370496,-4503599627370496]=[round(X)||X<-[4503599627370495.5,-4503599627370495.5]],\n    done.\nf(Bits) -> <<V:64/float>> = <<Bits:64>>, V.\nbits(V) -> <<B:64>> = <<V:64/float>>, B.\n";
    public const string SubnormalDirectedRounding = "-module(oracle_numeric_subnormal_directed_rounding).\n-export([run/0]).\nrun() ->\n    P=f(1), N=f(16#8000000000000001), {0,0,1,0}={round(P),trunc(P),ceil(P),floor(P)}, {0,0,0,-1}={round(N),trunc(N),ceil(N),floor(N)}, lists:foreach(fun(Z)->{0,0,0,0}={round(Z),trunc(Z),ceil(Z),floor(Z)} end,[f(0),f(16#8000000000000000)]),\n    done.\nf(Bits) -> <<V:64/float>> = <<Bits:64>>, V.\nbits(V) -> <<B:64>> = <<V:64/float>>, B.\n";
    public const string LargestFloatIntegers = "-module(oracle_numeric_largest_float_integers).\n-export([run/0]).\nrun() ->\n    P=f(16#7fefffffffffffff), N=f(16#ffefffffffffffff), I=(1 bsl 1024)-(1 bsl 971), J= -I, lists:foreach(fun(Op)->I=apply(erlang,Op,[P]),J=apply(erlang,Op,[N]) end,[round,trunc,ceil,floor]),\n    done.\nf(Bits) -> <<V:64/float>> = <<Bits:64>>, V.\nbits(V) -> <<B:64>> = <<V:64/float>>, B.\n";
    public const string HugeIntegerIdentity = "-module(oracle_numeric_huge_integer_identity).\n-export([run/0]).\nrun() ->\n    I=1 bsl 4096, J= -I, lists:foreach(fun(Op)->I=apply(erlang,Op,[I]),J=apply(erlang,Op,[J]) end,[round,trunc,ceil,floor]), I=abs(J),\n    done.\n";
    public const string InvalidTypePartitions = "-module(oracle_numeric_invalid_type_partitions).\n-export([run/0]).\nrun() ->\n    lists:foreach(fun(Op)->lists:foreach(fun(V)->bad(Op,V) end,[wrong,[],[x],[x|tail],{},#{},<<>>,<<1:1>>,self(),make_ref(),fun()->ok end]) end,[abs,float,round,trunc,ceil,floor]),\n    done.\nbad(Op,V) -> try apply(erlang,Op,[V]) of _ -> error(expected_badarg) catch error:badarg -> ok end.\n";
    public const string MinMaxTieIdentity = "-module(oracle_numeric_min_max_tie_identity).\n-export([run/0]).\nrun() ->\n    lists:foreach(fun(Op)->1=apply(erlang,Op,[1,1.0]),1.0=apply(erlang,Op,[1.0,1]),0=bits(apply(erlang,Op,[f(0),f(16#8000000000000000)])),16#8000000000000000=bits(apply(erlang,Op,[f(16#8000000000000000),f(0)])),{1}=apply(erlang,Op,[{1},{1.0}]),[1.0]=apply(erlang,Op,[[1.0],[1]]) end,[min,max]),\n    done.\nf(Bits) -> <<V:64/float>> = <<Bits:64>>, V.\nbits(V) -> <<B:64>> = <<V:64/float>>, B.\n";
    public const string MinMaxExactMixedComparison = "-module(oracle_numeric_min_max_exact_mixed_comparison).\n-export([run/0]).\nrun() ->\n    I=(1 bsl 53)+1, F=9007199254740992.0, F=min(I,F), F=min(F,I), I=max(I,F), I=max(F,I), N= -I, G= -F, N=min(N,G), N=min(G,N), G=max(N,G), G=max(G,N), 0=min(0,f(1)), 0=max(0,f(16#8000000000000001)),\n    done.\nf(Bits) -> <<V:64/float>> = <<Bits:64>>, V.\nbits(V) -> <<B:64>> = <<V:64/float>>, B.\n";
    public const string GuardAndMatchSpecRoutes = "-module(oracle_numeric_guard_and_match_spec_routes).\n-export([run/0]).\nrun() ->\n    yes=guard(-2.5), no=guard(wrong), lists:foreach(fun({Op,V,E})->{ok,E,[],[]}=erlang:match_spec_test({V},[{{'$1'},[],[{Op,'$1'}]}],table) end,[{abs,-2.5,2.5},{float,2,2.0},{round,-2.5,-3},{trunc,-2.5,-2},{ceil,-2.5,-2},{floor,-2.5,-3}]), {ok,1.0,[],[]}=erlang:match_spec_test({1.0,1},[{{'$1','$2'},[],[{min,'$1','$2'}]}],table),\n    done.\nguard(X) when abs(X)=:=2.5, float(X)=:= -2.5, round(X)=:= -3, trunc(X)=:= -2, ceil(X)=:= -2, floor(X)=:= -3, min(X,0)=:=X, max(X,0)=:=0 -> yes;\nguard(_) -> no.\n";
}
